      </div>

      <section v-if="caso" class="w-full bg-blueGray-200 pb-16">
        <div class="container mx-auto px-4">
          <div class="max-w-3xl mx-auto">

            <router-link to="/Casos"
              class="inline-flex items-center gap-2 text-teal-500 font-semibold mb-8 hover:text-teal-700 transition">
              <i class="fa-solid fa-arrow-left text-sm"></i>
              {{ $t('useCases.backToList') }}
            </router-link>

            <div class="bg-white rounded-lg shadow-lg p-8 md:p-12">

              <p class="text-sm italic text-blueGray-500 mb-8">
