              <div v-if="caso.tag === 'publicacion' && caso.reference" class="mb-2">
                <h3 class="text-xl font-semibold text-blueGray-700 mb-2">{{ $t('useCases.references') }}</h3>
                <p class="text-base text-blueGray-600 leading-relaxed">
