    <footer-component />
  </div>
</template>

<script>
import Navbar from "@/components/Navbars/AuthNavbar.vue";
import FooterComponent from "@/components/Footers/Footer.vue";
import casosDeUso from "@/data/casosDeUso.js";
import { useHead } from '@unhead/vue';

export default {
  components: {
    Navbar,
    FooterComponent,
  },

  computed: {
    caso() {
      return casosDeUso.find((c) => c.slug === this.$route.params.slug) || null;
    },
    content() {
      if (!this.caso) return {};
      return this.caso[this.$i18n.locale] || this.caso.es;
    },
  },

  created() {
    this.setSeo();
  },

  watch: {
    // Si cambia el slug (navegando de un caso a otro), actualiza el SEO
    '$route.params.slug': function () {
      this.setSeo();
    },
  },

  methods: {
    setSeo() {
      const pageTitle = this.caso
        ? `${this.stripHtml(this.content.title)} | EQUAIAR`
        : 'Caso de uso no encontrado | EQUAIAR';
      const pageDescription = this.caso ? this.stripHtml(this.content.excerpt) : '';

      useHead({
        title: pageTitle,
        meta: [
          { name: 'description', content: pageDescription },
          { property: 'og:type', content: 'article' },
          { property: 'og:title', content: pageTitle },
          { property: 'og:description', content: pageDescription },
        ],
      });
    },
    // Saca las etiquetas <em> antes de usar el texto en <title> o <meta>
    stripHtml(text) {
      return text ? text.replace(/<[^>]*>/g, '') : '';
    },
  },
};
</script>

