<template>
    <div>
        <navbar />
        <main>

            <!-- HERO -->
            <div class="relative w-full min-h-screen flex items-start justify-center overflow-hidden">
                <div class="absolute inset-0 w-full h-full" :style="{
                    backgroundImage: `url(${isMobile ? '/images/casos_hero_mobile.jpg' : '/images/casos_hero.jpg'})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center'
                }">
                    <span id="blackOverlay" class="w-full h-full absolute opacity-50 bg-black"></span>
                </div>
                <div class="container relative mx-auto px-4 z-10 w-full hero-text-container">
                    <div class="w-full lg:w-8/12 xl:w-7/12 mx-auto text-center">
                        <h1 class="text-white font-extrabold text-4xl sm:text-5xl lg:text-6xl">
                            {{ $t('useCases.title') }}
                        </h1>
                        <p
                            class="mt-6 text-xl lg:text-2xl text-blueGray-200 font-normal leading-relaxed max-w-3xl mx-auto px-4">
                            {{ $t('useCases.subtitle') }}
                        </p>


                    </div>
                </div>

                <!-- Decorador inferior: Curva Suave -->
                <div class="top-auto bottom-0 left-0 right-0 w-full absolute pointer-events-none overflow-hidden h-70-px"
                    style="transform: translateZ(0);">
                    <svg class="absolute bottom-0 overflow-hidden" xmlns="http://www.w3.org/2000/svg"
                        preserveAspectRatio="none" version="1.1" viewBox="0 0 2560 100" x="0" y="0">
                        <path fill="#F8FAFC" d="M0,0 C1280,100 1280,100 2560,0 L2560,100 L0,100 Z"></path>
                    </svg>
                </div>
            </div>

            <!-- LISTADO -->
            <section class="w-full bg-blueGray-200 py-16">
                <div class="container mx-auto px-4">
                    <div class="cases-grid">
                        <router-link v-for="caso in casos" :key="caso.slug" :to="`/Casos/${caso.slug}`"
                            class="case-card bg-white rounded-lg shadow-lg overflow-hidden flex flex-col transition-all duration-300 hover:shadow-2xl hover:-translate-y-1">

                            <div class="w-full overflow-hidden relative" style="height: 12rem;">
                                <img :src="caso.image" :alt="content(caso).title" class="w-full"
                                    style="height: 100%; object-fit: cover;" />
                                <div style="position: absolute; inset: 0; background-color: black; opacity: 0.2;"></div>
                            </div>

                            <div class="p-8 flex flex-col flex-grow">
                                <span v-if="caso.tag === 'publicacion'"
                                    class="text-xs uppercase font-bold text-teal-600 mb-2 block">
                                    {{ $t('useCases.tagPublication') }}
                                </span>
                                <span v-else class="text-xs uppercase font-bold text-teal-600 mb-2 block">
                                    {{ $t('useCases.tagPoligonar') }}
                                </span>
                                <h2 class="text-2xl font-semibold text-blueGray-700 mb-3" v-html="content(caso).title">
                                </h2>
                                <p class="text-lg text-blueGray-500 leading-relaxed mb-4 flex-grow"
                                    v-html="content(caso).excerpt"></p>
                                <span class="text-teal-500 font-semibold inline-flex items-center gap-2">
                                    {{ $t('useCases.readMore') }}
                                    <i class="fa-solid fa-arrow-right text-sm"></i>
                                </span>
                            </div>

                        </router-link>
                    </div>
                </div>
            </section>

        </main>
        <footer-component />
    </div>
</template>

<script>
import Navbar from "@/components/Navbars/AuthNavbar.vue";
import FooterComponent from "@/components/Footers/Footer.vue";
import casosDeUso from "@/data/casosDeUso.js";
import { useHead } from '@unhead/vue';

export default {
    components: {
        Navbar,
        FooterComponent,
    },

    created() {
        const pageTitle = 'Casos de uso destacados | EQUAIAR';
        const pageDescription = 'Una selección de proyectos en los que trabajamos. Cada caso describe el problema, cómo lo resolvimos y qué resultado obtuvo el equipo o la institución.';

        useHead({
            title: pageTitle,
            meta: [
                { name: 'description', content: pageDescription },
                { property: 'og:type', content: 'website' },
                { property: 'og:title', content: pageTitle },
                { property: 'og:description', content: pageDescription },
                { property: 'og:url', content: 'https://equaiar.com.ar/Casos' },
            ],
            link: [
                { rel: 'canonical', href: 'https://equaiar.com.ar/Casos' }
            ]
        })
    },

    data() {
        return {
            casos: casosDeUso,
            isMobile: false,
        };
    },
    mounted() {
        this.checkMobile();
        window.addEventListener('resize', this.checkMobile);
    },

    beforeUnmount() {
        window.removeEventListener('resize', this.checkMobile);
    },


    methods: {
        // Devuelve el contenido del caso en el idioma activo, con fallback a español
        content(caso) {
            return caso[this.$i18n.locale] || caso.es;
        },
        checkMobile() {
            this.isMobile = window.innerWidth < 768;
        },
    },
};
</script>

